{id:"v1",area:"Matemática",title:"Função quadrática",goal:"Relacionar expressão, raízes e vértice.",text:"f(x)=ax²+bx+c, a≠0. O sinal de a indica concavidade. Δ=b²−4ac determina raízes reais. Vértice: xv=−b/(2a), yv=f(xv).",examples:["a>0: concavidade para cima; mínimo.","a<0: para baixo; máximo.","Δ>0: duas raízes; Δ=0: uma dupla; Δ<0: nenhuma real."],tip:"Não confunda raízes (onde y=0) com o vértice (ponto extremo).",q:[["f(x)=x²−6x+5 tem vértice:",["(−3,−4)","(3,−4)","(3,4)"],1,"xv=3; f(3)=−4."],["Se a<0, a parábola:",["abre para cima","abre para baixo","não tem vértice"],1,"Coeficiente negativo indica concavidade para baixo."]]},
{id:"v2",area:"Física",title:"Movimento uniforme",goal:"Interpretar velocidade e posição.",text:"No movimento uniforme, v é constante e s=s₀+vt. Velocidade média é Δs/Δt. Em gráfico posição-tempo, a inclinação representa velocidade.",examples:["s₀=10m, v=3m/s, t=4s → s=22m.","1m/s=3,6km/h.","Converta unidades antes de substituir."],tip:"km/h para m/s: dividir por 3,6.",q:[["90 km em 1,5 h dá velocidade média:",["45 km/h","60 km/h","75 km/h"],1,"90÷1,5=60."],["A inclinação do gráfico posição-tempo indica:",["massa","velocidade","energia"],1,"É Δposição/Δtempo."]]},
{id:"v3",area:"Química",title:"Mol e massa molar",goal:"Converter massa e quantidade de matéria.",text:"n=m/M. Mol mede quantidade de matéria; um mol contém aproximadamente 6,022×10²³ entidades.",examples:["18g de água (M=18g/mol) correspondem a 1mol.","Massa molar: soma das massas atômicas da fórmula."],tip:"g ÷ (g/mol) resulta em mol.",q:[["36g de água, M=18g/mol, correspondem a:",["0,5mol","1mol","2mol"],2,"36/18=2."],["Um mol contém aproximadamente:",["6,02×10²³ entidades","6,02×10²","1000"],0,"Constante de Avogadro."]]},
{id:"v4",area:"Português",title:"Tese, argumento e inferência",goal:"Identificar posição central e evidências.",text:"Tese é a ideia defendida. Argumentos sustentam a tese. Inferência é conclusão derivada de pistas textuais, não suposição sem base.",examples:["Tese: leitura profunda deve ser valorizada.","Argumento: permite acompanhar raciocínios e evidências.","A inferência precisa ser apoiada pelo texto."],tip:"Exija evidência textual para cada alternativa.",q:[["Tese é:",["um exemplo isolado","a posição central defendida","o título sempre"],1,"Tese é a posição central."],["Inferência válida deve:",["ignorar o texto","basear-se em pistas","ser opinião"],1,"Use pistas e contexto."]]}
