const AI_ENDPOINT_KEY="mfo:preferences:tutor-endpoint";let aiHistory=[];
function aiPage(){
 document.getElementById("s-ai").innerHTML='<div class="eyebrow">MENTORIA ADAPTATIVA · IA</div><h1 class="screenTitle">Tutor Mind Forge</h1><p class="lead">Um parceiro de estudo para explicar, questionar, dar pistas graduais e ajudar você a perceber onde seu raciocínio precisa melhorar. Não substitui livros, professores nem fontes oficiais.</p><article class="card ai-panel section"><div class="heading"><div><h2>Converse sobre o que está estudando</h2><p>Escolha a área, escreva sua dúvida e peça uma explicação no nível certo.</p></div></div><p class="small" role="note">Privacidade: ao enviar ao Tutor integrado, sua pergunta e parte do histórico saem deste aparelho e são encaminhados ao serviço de IA configurado. Não envie dados pessoais. Respostas de IA podem conter erros; confira informações importantes.</p><div class="field"><label for="ai-area">Área de estudo</label><select id="ai-area"><option value="Estudo geral">Estudo geral</option><option value="Inglês">Inglês</option><option value="PAS/UEM e vestibulares">PAS/UEM e vestibulares</option><option value="Física">Física</option><option value="Química">Química</option><option value="Matemática">Matemática</option><option value="Lógica e programação">Lógica e programação</option><option value="OBMEP e olimpíadas matemáticas">OBMEP e olimpíadas matemáticas</option><option value="Redação e interpretação">Redação e interpretação</option></select></div><div class="ai-quick"><button class="btn" data-ai-prompt="Explique este assunto do zero, com analogia, teoria, exemplo resolvido e uma questão para eu tentar: ">Explicar do zero</button><button class="btn" data-ai-prompt="Não me dê a resposta ainda. Faça perguntas e dê pistas graduais para eu resolver: ">Quero pistas</button><button class="btn" data-ai-prompt="Crie 5 questões progressivas e só mostre o gabarito depois das minhas tentativas sobre: ">Gerar exercícios</button><button class="btn" data-ai-prompt="Analise meu raciocínio, identifique o erro conceitual e mostre como melhorar. Meu raciocínio é: ">Corrigir raciocínio</button></div><div id="ai-chat" class="ai-chat" aria-live="polite"><div class="ai-message assistant">Olá! Sou o Tutor Mind Forge. Posso explicar, propor desafios e ajudar você a construir o raciocínio. Comece escrevendo sua dúvida abaixo.</div></div><div class="ai-compose"><label for="ai-question" class="small">Sua pergunta ou tentativa</label><textarea id="ai-question" maxlength="3000" placeholder="Ex.: Não entendi por que a velocidade é a inclinação do gráfico posição × tempo..."></textarea><div class="ai-actions"><button class="btn primary" id="ai-send">Enviar ao tutor ↗</button><button class="btn" id="ai-open-chatgpt">Abrir esta pergunta no ChatGPT ↗</button><button class="btn" id="ai-clear">Limpar conversa</button></div><div id="ai-status" class="ai-status" role="status">A integração por API é ativada depois que o endpoint seguro do Worker for configurado. O botão ChatGPT funciona como alternativa imediata.</div></div></article><details class="ai-config section" open><summary>Conectar a IA ao site (configuração única)</summary><p class="small">Cole aqui a URL pública do Cloudflare Worker depois de implantá-lo. A chave da OpenAI fica guardada como segredo no servidor — nunca neste site nem no GitHub.</p><div class="field"><label for="ai-endpoint">URL do Tutor Mind Forge</label><input id="ai-endpoint" type="url" placeholder="https://mind-forge-tutor.seuusuario.workers.dev/api/tutor"></div><div class="ai-actions"><button class="btn" id="ai-save-endpoint">Salvar endereço</button><button class="btn" id="ai-test-endpoint">Testar conexão</button><a class="btn" href="https://github.com/mateusvidotto-dotcom/INTELIGENCIAGAME2.0/blob/main/AI_SETUP.md" target="_blank" rel="noopener noreferrer">Ver guia de instalação ↗</a></div><p class="small" id="ai-config-status"></p></details><div class="small section">Privacidade: as mensagens enviadas ao tutor integrado são encaminhadas ao provedor de IA pelo Worker. A conversa desta interface fica apenas em memória até você limpar ou recarregar a página. Não envie senhas, dados pessoais ou informações sensíveis.</div>';
 document.getElementById("ai-endpoint").value=tutorEndpoint();
 const questionBox=document.getElementById("ai-question");questionBox.addEventListener("keydown",e=>{if((e.ctrlKey||e.metaKey)&&e.key==="Enter")sendToTutor()});
}
function addAIMessage(role,text){const chat=document.getElementById("ai-chat");const node=document.createElement("div");node.className="ai-message "+role;node.textContent=text;chat.appendChild(node);chat.scrollTop=chat.scrollHeight}
function tutorEndpoint(){let value=localStorage.getItem(AI_ENDPOINT_KEY);if(value===null){const old=localStorage.getItem("mindforge.tutorEndpoint");if(old!==null){value=old;try{localStorage.setItem(AI_ENDPOINT_KEY,old)}catch(e){}}}return (value||"").trim()}
function saveTutorEndpoint(){const field=document.getElementById("ai-endpoint"),value=field.value.trim();if(value){try{const u=new URL(value);if((u.protocol!=="https:"&&u.hostname!=="localhost")||u.username||u.password)throw new Error();}catch{document.getElementById("ai-config-status").textContent="Informe uma URL HTTPS válida do Worker, sem usuário ou senha.";return}}try{localStorage.setItem(AI_ENDPOINT_KEY,value);document.getElementById("ai-config-status").textContent=value?"Endereço salvo neste navegador. A chave da API não é armazenada aqui.":"Endereço removido."}catch(e){document.getElementById("ai-config-status").textContent="Não foi possível salvar a URL neste navegador."}}
async function testTutorEndpoint(){const endpoint=tutorEndpoint(),status=document.getElementById("ai-config-status");if(!endpoint){status.textContent="Configure primeiro a URL do Worker.";return}status.textContent="Testando...";try{const base=new URL(endpoint);const response=await fetch(base.origin+"/health",{method:"GET"});if(!response.ok)throw new Error("HTTP "+response.status);const data=await response.json();status.textContent=data.ok?"Conexão com o Worker confirmada.":"O Worker respondeu, mas não confirmou o estado."; }catch(err){status.textContent="Não foi possível conectar. Confira URL, implantação e CORS. "+err.message}}
async function sendToTutor(){
 const field=document.getElementById("ai-question"),question=field.value.trim(),status=document.getElementById("ai-status"),button=document.getElementById("ai-send"),endpoint=tutorEndpoint(),area=document.getElementById("ai-area").value;
 if(!question){status.textContent="Escreva uma pergunta ou seu raciocínio primeiro.";return}
 if(!endpoint){status.textContent="A API ainda não foi conectada. Use 'Abrir esta pergunta no ChatGPT' agora ou siga o guia para ativar o Tutor integrado.";return}
 addAIMessage("user",question);aiHistory.push({role:"user",content:question});field.value="";button.disabled=true;button.textContent="Pensando...";
 status.textContent="O tutor está analisando sua pergunta...";
 try{
  const response=await fetch(endpoint,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({area,question,history:aiHistory.slice(0,-1).slice(-8)})});
  const payload=await response.json();if(!response.ok)throw new Error(payload.error||("HTTP "+response.status));
  const answer=String(payload.answer||"Não recebi uma resposta em texto.");addAIMessage("assistant",answer);aiHistory.push({role:"assistant",content:answer});aiHistory=aiHistory.slice(-8);status.textContent="Resposta recebida. Confira os passos e valide informações importantes em fontes confiáveis.";
 }catch(err){status.textContent="Falha na conexão com o tutor: "+err.message+" Confira se o Worker está ativo e se a URL foi copiada corretamente.";addAIMessage("assistant","Não consegui acessar a IA agora. Sua pergunta não foi perdida no código do site; tente novamente ou use o botão para abrir no ChatGPT.")}
 finally{button.disabled=false;button.textContent="Enviar ao tutor ↗"}
}
function openCurrentQuestionInChatGPT(){const question=document.getElementById("ai-question").value.trim();if(!question){document.getElementById("ai-status").textContent="Escreva uma pergunta primeiro.";return}const area=document.getElementById("ai-area").value;const prompt="Atue como meu tutor pedagógico. Área: "+area+". Explique com rigor, em português claro, passo a passo. Não entregue somente a resposta: ajude-me a raciocinar, use exemplos e termine com uma questão curta para verificar a compreensão. Dúvida: "+question;window.open("https://chatgpt.com/?q="+encodeURIComponent(prompt),"_blank","noopener,noreferrer")}


function escapeHTML(value){return String(value===null||value===undefined?"":value).replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]))}
function lessonExams(l){return !l||!l.exams?[]:(Array.isArray(l.exams)?l.exams:[l.exams])}
function lessonHasExam(l,exam){return lessonExams(l).includes(exam)}
function examOptionsForPath(){return Array.from(new Set(C[path].filter(l=>!l.isSession).flatMap(l=>lessonExams(l)))).sort()}
function subjectOptionsForPath(){return Array.from(new Set(C[path].filter(l=>!l.isSession&&(examFilter==="Todos"||lessonHasExam(l,examFilter))).map(l=>l.area||l.topic).filter(Boolean))).sort()}
function activeQuestions(){return sessionQuestions||(find(unit)?.q||[])}
function currentSourceLesson(){return sessionSourceIds?find(sessionSourceIds[qi]):find(unit)}
function renderExamTags(l){return lessonExams(l).map(x=>'<span class="exam-tag">'+escapeHTML(x)+'</span>').join("")}
function renderDetailedFeedback(q){
 const a=q[4]||{},right=q[2],correct=sel===right,letter=n=>String.fromCharCode(65+n);
 const alternatives=Array.isArray(a.alternatives)?a.alternatives:[];
 const steps=Array.isArray(a.steps)?a.steps:[q[3]||"Retome o conceito central e verifique as condições do enunciado."];
 const selectedLabel=correct?"Sua resposta correta: ":"Sua resposta: ";
 return '<section class="detailed-feedback" aria-live="polite">'+
  '<h3>'+(correct?'Análise da resposta — você acertou':'Análise da resposta — vamos corrigir o raciocínio')+'</h3>'+
  '<div class="feedback-status '+(correct?'correct':'incorrect')+'">'+(correct?'✓ Correto. ':'✕ Ainda não. ')+selectedLabel+'alternativa '+letter(sel)+'. Gabarito: alternativa '+letter(right)+'.</div>'+
  '<div class="feedback-block"><h4>1 · Conceito avaliado</h4><p>'+escapeHTML(a.concept||q[3]||"Compreenda o conceito central e sua aplicação no enunciado.")+'</p></div>'+
  '<div class="feedback-block"><h4>2 · Resolução passo a passo</h4><ol>'+steps.map(x=>'<li>'+escapeHTML(x)+'</li>').join("")+'</ol></div>'+
  '<div class="feedback-block"><h4>3 · Análise de todas as alternativas</h4><div class="alternative-review">'+q[1].map((option,i)=>'<div class="alternative-explanation '+(i===right?'is-correct':i===sel?'is-selected-wrong':'')+'"><strong>'+(i===right?'✓ Gabarito · ':i===sel?'Sua escolha · ':'Alternativa · ')+'('+letter(i)+') '+escapeHTML(option)+'</strong>'+escapeHTML(alternatives[i]||(i===right?'Esta alternativa corresponde ao conceito e às condições do enunciado.':'Esta alternativa não corresponde ao que foi solicitado.'))+'</div>').join("")+'</div></div>'+
  (a.trap?'<div class="feedback-block"><h4>4 · Armadilha comum</h4><p>'+escapeHTML(a.trap)+'</p></div>':'')+
  (a.takeaway?'<div class="analysis-takeaway"><b>O que levar para a próxima questão:</b> '+escapeHTML(a.takeaway)+'</div>':'')+
  '<div class="buttons"><button class="btn" id="explain-with-ai">Aprofundar com o Tutor IA ↗</button><span class="small">A explicação aparece tanto no acerto quanto no erro.</span></div></section>';
}
