/* Original ambient loop generated in Web Audio — no third-party recording. */
let ambientContext=null,ambientMaster=null,ambientTimer=null,ambientEnabled=false,ambientChord=0;
const ambientChords=[[146.83,220,293.66,369.99],[110,164.81,220,261.63],[123.47,185,246.94,293.66],[98,146.83,196,246.94]];
function playAmbientChord(){
 if(!ambientEnabled||!ambientContext)return;
 const now=ambientContext.currentTime,chord=ambientChords[ambientChord%ambientChords.length];
 chord.forEach((frequency,index)=>{const osc=ambientContext.createOscillator(),gain=ambientContext.createGain();osc.type=index===0?"sine":"triangle";osc.frequency.value=frequency;gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(index===0?.018:.009,now+1.7);gain.gain.setValueAtTime(index===0?.018:.009,now+6.3);gain.gain.exponentialRampToValueAtTime(.0001,now+7.8);osc.connect(gain);gain.connect(ambientMaster);osc.start(now);osc.stop(now+7.9)});
 ambientChord=(ambientChord+1)%ambientChords.length;ambientTimer=setTimeout(playAmbientChord,7800);
}
async function toggleAmbientMusic(){
 const button=document.getElementById("music-toggle");
 if(ambientEnabled){ambientEnabled=false;clearTimeout(ambientTimer);if(ambientMaster&&ambientContext){ambientMaster.gain.cancelScheduledValues(ambientContext.currentTime);ambientMaster.gain.setTargetAtTime(.0001,ambientContext.currentTime,.12)}button.textContent="♫ Ativar música";button.classList.remove("music-on");button.setAttribute("aria-pressed","false");setTimeout(()=>{if(!ambientEnabled&&ambientContext){ambientContext.close().catch(()=>{});ambientContext=null;ambientMaster=null}},500);return}
 const AudioCtx=window.AudioContext||window.webkitAudioContext;if(!AudioCtx){button.textContent="Áudio indisponível";return}
 try{ambientContext=new AudioCtx();await ambientContext.resume();ambientMaster=ambientContext.createGain();ambientMaster.gain.value=.68;ambientMaster.connect(ambientContext.destination);ambientEnabled=true;ambientChord=0;playAmbientChord();button.textContent="♫ Desligar música";button.classList.add("music-on");button.setAttribute("aria-pressed","true")}catch(e){button.textContent="Não foi possível ativar";ambientEnabled=false}
}

document.getElementById("music-toggle").addEventListener("click",toggleAmbientMusic);document.addEventListener("visibilitychange",()=>{if(!ambientContext)return;if(document.hidden)ambientContext.suspend().catch(()=>{});else if(ambientEnabled)ambientContext.resume().catch(()=>{})});
document.addEventListener("click",e=>{if(e.target.closest("#mobile-more-toggle")){const menu=document.getElementById("mobile-more"),toggle=document.getElementById("mobile-more-toggle"),open=menu.classList.toggle("hide")===false;toggle.setAttribute("aria-expanded",String(open));return}if(!e.target.closest("#mobile-more")){const menu=document.getElementById("mobile-more"),toggle=document.getElementById("mobile-more-toggle");if(menu)menu.classList.add("hide");if(toggle)toggle.setAttribute("aria-expanded","false")}let n=e.target.closest("[data-nav]");if(n){show(n.dataset.nav,true);return}let p=e.target.closest("[data-path]");if(p){path=p.dataset.path;examFilter="Todos";subjectFilter="Todas";if(path==="logic")show("logic",true);else show(path==="english"?"english":"courses",true);return}let u=e.target.closest("[data-unit],[data-open]");if(u){unit=u.dataset.unit||u.dataset.open;path=pathOf(unit);show("lesson",true);return}let a=e.target.closest("[data-answer]");if(a&&!revealed){sel=+a.dataset.answer;quiz();return}if(e.target.id==="startquiz")startQuiz();if(e.target.id==="check")check();if(e.target.id==="next")next();if(e.target.id==="mark"){d.done[unit]=true;save();show("courses")}if(e.target.id==="hint")alert("Pista: releia a definição e descarte as alternativas incompatíveis.");if(e.target.id==="start-simulation")startFilteredSimulation();if(e.target.id==="save-writing"){d.writingResponses=d.writingResponses||{};d.writingResponses[unit]=document.getElementById("writing-response").value;if(save())document.getElementById("writing-save-state").textContent="Rascunho salvo neste navegador.";else document.getElementById("writing-save-state").textContent="Não foi possível salvar; confira o espaço disponível."}if(e.target.id==="writing-to-ai"){const l=find(unit),answer=document.getElementById("writing-response").value;show("ai");document.getElementById("ai-question").value="Analise meu texto com critérios de vestibular. Tema: "+l.writing.prompt+"\n\nMeu texto:\n"+answer+"\n\nAvalie tese, estrutura, argumentação, coesão, gramática e propostas concretas de melhoria. Não invente nota oficial."}if(e.target.id==="explain-with-ai"){const q=activeQuestions()[qi],l=currentSourceLesson()||find(unit);const prompt="Faça uma análise aprofundada desta questão de "+(l?.area||l?.topic||"estudo")+". Enunciado: "+q[0]+"\nAlternativas: "+q[1].map((x,i)=>String.fromCharCode(65+i)+") "+x).join("\n")+"\nMinha resposta: "+String.fromCharCode(65+sel)+"\nGabarito: "+String.fromCharCode(65+q[2])+". Explique passo a passo, o conceito, por que cada alternativa está certa ou errada e crie uma questão de transferência.";show("ai");document.getElementById("ai-question").value=prompt;}if(e.target.id==="ai-send")sendToTutor();if(e.target.id==="ai-save-endpoint")saveTutorEndpoint();if(e.target.id==="ai-test-endpoint")testTutorEndpoint();if(e.target.id==="ai-open-chatgpt")openCurrentQuestionInChatGPT();if(e.target.id==="ai-clear"){aiHistory=[];document.getElementById("ai-chat").innerHTML="";addAIMessage("assistant","Conversa limpa. Qual assunto vamos estudar?")}let template=e.target.closest("[data-ai-prompt]");if(template){const q=document.getElementById("ai-question");q.value=template.dataset.aiPrompt+q.value;q.focus()}if(e.target.id==="saveprofile"){d.profile.exam=document.getElementById("exam").value;d.profile.year=document.getElementById("year").value.trim();if(save())alert("Meta salva neste navegador.");else alert("Não foi possível salvar.")}if(e.target.id==="mfo-save-preferences"){const ok=MindForgePlatform.savePreferences({theme:document.getElementById("mfo-theme").value,reducedMotion:document.getElementById("mfo-reduced-motion").checked});document.getElementById("mfo-preferences-status").textContent=ok?"Preferências aplicadas e salvas.":"Não foi possível salvar as preferências."}if(e.target.id==="export"){try{const payload=MindForgePlatform.buildBackup(d),blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download="mind-forge-backup-v2.json";link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(error){alert("Não foi possível exportar: "+error.message)}}if(e.target.id==="reset"&&confirm("Apagar o progresso dos três pilares e as preferências visuais deste aparelho? Esta ação não pode ser desfeita. Exporte um backup antes.")){MindForgePlatform.clearMainState();MindForgePlatform.resetPreferences();MindForgeEnglish.resetProgress();MindForgeLogic.resetProgress();location.reload()}});
document.addEventListener("change",e=>{if(e.target.id==="exam-filter"){examFilter=e.target.value;subjectFilter="Todas";courses();return}if(e.target.id==="subject-filter"){subjectFilter=e.target.value;courses();return}if(e.target.id==="import"){let f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024){alert("Backup acima de 2 MB.");e.target.value="";return}let r=new FileReader();r.onload=()=>{try{const checked=MindForgePlatform.validateBackup(JSON.parse(r.result));if(!checked.ok)throw Error(checked.error);const note=checked.legacy?"Backup antigo: apenas o painel principal será substituído; os outros módulos serão preservados.":"Backup completo: painel principal, inglês, lógica e preferências serão substituídos.";if(!confirm(note+"\n\nDeseja continuar?"))return;d=checked.data.modules.main;if(!save())throw Error("Falha ao salvar o painel principal.");if(checked.data.modules.english!==null&&!MindForgeEnglish.importProgress(checked.data.modules.english))throw Error("Falha ao restaurar o English Forge.");if(checked.data.modules.logic!==null&&!MindForgeLogic.importProgress(checked.data.modules.logic))throw Error("Falha ao restaurar o Logic Forge.");if(!MindForgePlatform.savePreferences(checked.data.preferences))throw Error("Falha ao salvar preferências.");show("home");alert("Backup importado.")}catch(error){alert("Não foi possível importar: "+error.message)}finally{e.target.value=""}};r.readAsText(f)}});
