function updateOfflineNotice(){const notice=document.getElementById("offline-notice");if(notice)notice.hidden=navigator.onLine;}window.addEventListener("online",updateOfflineNotice);window.addEventListener("offline",updateOfflineNotice);updateOfflineNotice();document.getElementById("ai-question")?.addEventListener("keydown",e=>{if((e.ctrlKey||e.metaKey)&&e.key==="Enter")sendToTutor()});const routes=new Set(["home","english","logic","courses","lesson","quiz","review","stats","settings","ai"]);function routeFromHash(){const v=(location.hash||"").replace(/^#\/?/,"");return routes.has(v)?v:"home"}const first=routeFromHash();if(!location.hash)history.replaceState({view:first},"","#/"+first);window.addEventListener("popstate",()=>show(routeFromHash(),false));show(first,false);
